      'destroy_vm_instance': '#dc2626',
      'page_uses_bts_vm': '#2563eb',
      'BTSRuntime::Destroy': '#7c3aed',
      'will_capture_snapshot': '#059669',
      'shared_bts_possible_leak': '#e11d48',
